package com.bank.core;

import java.util.Objects;

// RISKY: equals overridden, hashCode inherited (identity-based).
public class HalfAccount {
    private final String accountId;
    public HalfAccount(String accountId) { this.accountId = accountId; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof HalfAccount)) return false;
        return Objects.equals(accountId, ((HalfAccount) o).accountId);
    }
    // NO hashCode → equal objects scatter across buckets.
}
