package com.bank.core;

import java.util.Objects;

// CORRECT: both overridden from the same field.
public class FullAccount {
    private final String accountId;
    public FullAccount(String accountId) { this.accountId = accountId; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof FullAccount)) return false;
        return Objects.equals(accountId, ((FullAccount) o).accountId);
    }
    @Override
    public int hashCode() { return Objects.hash(accountId); }
}
