package com.bank.core;

import java.util.*;
import java.util.logging.*;

public class OnlyEqualsDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // RISK 1: HashMap lookup fails.
        Map<HalfAccount, String> tier = new HashMap<>();
        tier.put(new HalfAccount("SAV2001"), "PREMIUM");
        String got = tier.get(new HalfAccount("SAV2001"));
        log.warning(() -> "HalfAccount map lookup (expected null) → " + got);

        // RISK 2: HashSet keeps duplicates.
        Set<HalfAccount> half = new HashSet<>();
        half.add(new HalfAccount("SAV2001"));
        half.add(new HalfAccount("SAV2001"));
        log.warning(() -> "HalfAccount set size (expected 2, duplicate!) → " + half.size());

        // FIXED: both overridden.
        Map<FullAccount, String> tier2 = new HashMap<>();
        tier2.put(new FullAccount("SAV2001"), "PREMIUM");
        log.info(() -> "FullAccount map lookup → " + tier2.get(new FullAccount("SAV2001")));

        Set<FullAccount> full = new HashSet<>();
        full.add(new FullAccount("SAV2001"));
        full.add(new FullAccount("SAV2001"));
        log.info(() -> "FullAccount set size (expected 1) → " + full.size());
    }
}
